import icontract
from typing import List


@icontract.require(lambda a: len(a) > 0)
@icontract.ensure(lambda a, result: all(result <= x for x in a))
@icontract.ensure(lambda a, result: result in a)
def minArray(a: List[int]) -> int:
    result = a[0]
    for x in a[1:]:
        if x < result:
            result = x
    return result
